use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

struct Node;

const MAX_ROUNDS: usize = 8;

fn intent_label(intent: &Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // Contract precondition: len(question) <= 512. It is guaranteed of every
        // input, but we fail closed rather than forward an over-long question.
        if ctx.question.len() > 512 {
            return ResponseResult::Error(LlmError {
                message: "question exceeds 512 bytes".to_string(),
            });
        }

        let system = format!(
            "You are a customer-support agent. Intent: {}. \
             Answer the user's question using only the provided knowledge and any \
             information returned by the `lookup` tool. Do not invent facts.",
            intent_label(&ctx.intent)
        );

        // Seed the prompt with the question and whatever knowledge we were handed.
        let mut prompt = String::new();
        prompt.push_str("Question:\n");
        prompt.push_str(&ctx.question);
        if !ctx.knowledge.is_empty() {
            prompt.push_str("\n\nKnowledge:");
            for entry in &ctx.knowledge {
                prompt.push_str("\n- ");
                prompt.push_str(entry);
            }
        }

        // Tool-orchestration loop: the model either answers, or asks for a tool.
        // The only tool in this node's authority is `lookup` (kb-read).
        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(&system, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    if req.tool == "lookup" {
                        let results = kb_read::lookup(&req.query);
                        prompt.push_str("\n\nTool `lookup` result for query: ");
                        prompt.push_str(&req.query);
                        if results.is_empty() {
                            prompt.push_str("\n(no matches)");
                        } else {
                            for r in &results {
                                prompt.push_str("\n- ");
                                prompt.push_str(r);
                            }
                        }
                    } else {
                        // The node holds no authority for any other tool. Report
                        // it back to the model rather than attempting the call.
                        prompt.push_str("\n\nTool `");
                        prompt.push_str(&req.tool);
                        prompt.push_str("` is not available to this node.");
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool loop did not converge on an answer".to_string(),
        })
    }
}

export!(Node);
```

